-- 检测活动时间
function RouletteMould_ChkTime(nRouletteId,nUserId)
	if tRouletteMould_Info[nRouletteId]["ActivityTime"] == nil then
	
		return true
	end
	
	local sActiveTime = tRouletteMould_Info[nRouletteId]["ActivityTime"]
	if not Sys_ChkFullTime(sActiveTime) then
		-- 过期处理
		local nItemId = tRouletteMould_Info[nRouletteId]["OverdueItemId"]
		
		if nItemId ~= nil and Item_ChkItem(nItemId,nil,nil,nUserId) then
			Item_DelAllItemByType(nItemId,nUserId)
			local sText = string.format("0,0,%d,1,%d,2,0,0",nItemId,nRouletteId)
			Sys_SaveActionFestivalLog(sText,nUserId)
			RouletteMould_Msg(nRouletteId,"OverdueItem",nil,nUserId)
		end
		
		return false
	end
	
	return true
end

-- 提示
function RouletteMould_Msg(nRouletteId,sType,nNum,nUserId)
	local sContent = ""
	
	if tRouletteMould_Info[nRouletteId]["Tip"] == nil or tRouletteMould_Info[nRouletteId]["Tip"][sType] == nil then
		local sNewContent = tRouletteMould_Text[sType]
		if sType == "NoItem" then
			local nItemId = tRouletteMould_Info[nRouletteId]["Cost"]["DeleteItem"][1]["Id"]
			sContent = string.format(sNewContent,nNum,Get_ItemtypeName(nItemId))
		elseif string.find(sType,"Again") then
			sContent = string.format(sNewContent,nNum)
		elseif nNum ~= nil then
			
			local nValue = tRouletteMould_Info[nRouletteId]["Cost"][sType]*nNum
			sContent = string.format(sNewContent,nValue)
			
		else
			sContent = sNewContent
		end
	else
		sContent = tRouletteMould_Info[nRouletteId]["Tip"][sType]
		if sType == "OverTip" then
			if nNum > 1 and tRouletteMould_Info[nRouletteId]["Tip"]["OverTipTen"] ~= nil then
				local sContentNew = tRouletteMould_Info[nRouletteId]["Tip"]["OverTipTen"]
				-- 代表要传参数
				local nIndex = tRouletteMould_Info[nRouletteId]["Tip"]["TipIndex"]
				if nIndex ~= nil then
					local nData = RouletteMould_GetStc(nRouletteId,nIndex,nUserId)
					sContent = string.format(sContentNew,nData)
				else
					sContent = sContentNew
				end
			end
		end
	end

	if sContent == nil then
		return
	end
	
	User_TalkChannel2005(sContent,nUserId)
end

-- 打log
function RouletteMould_OutLog(sText,nNowUserId)
	if type(sText) ~= "string" then
		Sys_SaveAbnormalLog("函数 RouletteMould_OutLog 中 sText 只能传字符")
		return
	end
	
	local nUserId = nNowUserId or Get_UserId()
	local sUserName = Get_UserName(nUserId)
	local nUserLev = Get_UserLevel(nUserId)
	local nUserPro = Get_UserProfession(nUserId)
	local nUserMeto = Get_UserMetempsychosis(nUserId) 
	local nUserMapId = Get_UserMapId(nUserId)
	local sLogUserData = sUserName..'['.. nUserId ..']['.. nUserLev ..']['.. nUserPro ..']['.. nUserMeto ..'][' .. nUserMapId .. ']'

	local sLogFile = "gmlog/roulette_log"
	local sLogText = string.format("%s,%s",sLogUserData,sText)
	return SaveCustomLog(sLogFile,sLogText)
end

function RouletteMould_OutEmoneyLog(sText,nUserId)
	if type(sText) ~= "string" then
		Sys_SaveAbnormalLog("函数 RouletteMould_OutEmoneyLog 中 sText 只能传字符")
		return
	end
	return Sys_SaveEmoneyBuy(sText,nUserId)
end
-- 获取掩码
function RouletteMould_GetStc(nRouletteId,nIndex,nUserId)
	local tStcIndex = tRouletteMould_Info[nRouletteId]["Stc"]
	if tStcIndex == nil then
		return 0
	end
	
	local nEvent = tStcIndex[nIndex]["EventType"]
	local nType = tStcIndex[nIndex]["DataType"]
	local nData = Get_UserStatisticValue(nEvent,nType,nUserId)
	local nNowSingleData = nData%10000
	return nNowSingleData
end

-- 检测掩码限制
function RouletteMould_ChkStc(nRouletteId,nNum,nUserId)
	local tStcIndex = tRouletteMould_Info[nRouletteId]["Stc"]
	local nNewNum = nNum or 1
	if tStcIndex == nil then
		return true
	end
	for i,v in pairs(tStcIndex) do
		local nEvent = v["EventType"]
		local nType = v["DataType"]
		
		local nSingleData = v["RewardData"] or 1
		local nTotalData = v["RewardTotalData"]
		local nDelay = v["RewardDelay"]
		local nTimeType = v["RewardTimeType"]
		local nData = Get_UserStatisticValue(nEvent,nType,nUserId)
		
		-- 对掩码值进行分解，取出总的次数跟今天的次数
		local nNowSingleData = nData%10000
		local nNowTotalData = (nData - nNowSingleData)/10000

		if (nTotalData ~= nil) and (nNowTotalData >= nTotalData) then
			return false
		end
		
		-- 判断是否需要清除掩码的操作
		if (nDelay ~= nil) and (nTimeType ~= nil) and Task_StcInterval(nEvent,nType,nDelay,nTimeType,nUserId) then
			nNowSingleData = 0
			nData = nNowTotalData*10000 + nNowSingleData
			Task_SetStatistic(nEvent,nType,nData,1,nUserId)
			Task_SetStcTimestamp(nEvent,nType,0,nUserId)
		end
		
		-- 判断今天是否领取过奖励
		if nNowSingleData+nNewNum > nSingleData then
			return false
		end
	end
	
	return true
end

-- 检测是否是使用物品
function RouletteMould_ChkItem(nRouletteId,nNum,nUserId)
	local tDelItem = tRouletteMould_Info[nRouletteId]["Cost"]["DeleteItem"]
	
	if tDelItem == nil then
		return true
	end
	
	for i,v in pairs(tDelItem) do
		local nItemId = v["Id"]
		local nMonopoly = v["Monopoly"] or 1
		local nSash = v["Sash"] or 0
		local nItemNum = v["ItemNum"] or 1
		local nSaveTime = v["SaveTime"] or 1
		nItemNum = nItemNum * nNum
		nSaveTime = RewardTemplate_DelSaveItem(nItemId,nSaveTime)
		
		if not Item_ChkMulItem(nItemId,nItemId,nItemNum,nMonopoly,nSash,nUserId,nSaveTime) then
			return false
		end
	end
	
	return true
end

-- 检测天石是否满足
function RouletteMould_ChkEMoney(nRouletteId,nNum,nUserId)
	--12月轮盘活动
	if nRouletteId == 4290 then
		local nEvent = tRouletteMould_Info[nRouletteId]["Stc"][1]["EventType"]
		local nData = tRouletteMould_Info[nRouletteId]["Stc"][1]["DataType"]
		local nNumGet = Get_UserStatisticValue(nEvent,nData,nUserId)
		local nNum = nNumGet%10000
		--每人每天限量最多抽50次。
		--前10次花费5999天石，
		--从第11次起，到20次，每次5499天石,
		--从第21次起，到40次，每次4999天石,
		--从41次起，到50次，每次4499天石，
		if (nNum >= RouletteMould_HairBound[1][1]) and (nNum <= RouletteMould_HairBound[1][2]) then
			tRouletteMould_Info[nRouletteId]["Cost"]["Emoney"] = RouletteMould_HairBound[1][3]
			tRouletteMould_Info[nRouletteId]["Cost"]["EmoneyLog"] = "1000	01275	%d	%d	1	"
			elseif (nNum >= RouletteMould_HairBound[2][1]) and (nNum <= RouletteMould_HairBound[2][2]) then
				tRouletteMould_Info[nRouletteId]["Cost"]["Emoney"] = RouletteMould_HairBound[2][3]
				tRouletteMould_Info[nRouletteId]["Cost"]["EmoneyLog"] = "1000	01275	%d	%d	1	"
					elseif (nNum >= RouletteMould_HairBound[3][1]) and (nNum <= RouletteMould_HairBound[3][2]) then
					tRouletteMould_Info[nRouletteId]["Cost"]["Emoney"] = RouletteMould_HairBound[3][3] 
					tRouletteMould_Info[nRouletteId]["Cost"]["EmoneyLog"] = "1000	01275	%d	%d	1	"
						else
						tRouletteMould_Info[nRouletteId]["Cost"]["Emoney"] = RouletteMould_HairBound[4][3] 
						tRouletteMould_Info[nRouletteId]["Cost"]["EmoneyLog"] = "1000	01275	%d	%d	1	"
		end
	end
	local nEmoney = tRouletteMould_Info[nRouletteId]["Cost"]["Emoney"]
	
	if nEmoney == nil then
		return true
	end
	
	if type(nEmoney) ~= "number" then
		return false
	end
	
	local nUseEmoney = nEmoney*nNum
	local nUserEmoney = Get_UserEMoney(nUserId)
	
	if nUseEmoney > nUserEmoney then
		return false
	end
	
	return true
end

