		--每人每天限量最多抽10次。
		--前5次花费10000赠点，
		--从第6次起，到8次，每次12000赠点；
		--从9次起，到10次，每次13000赠点。
		if (nNum >= RouletteMould_Bound[nRouletteId][1][1]) and (nNum <= RouletteMould_Bound[nRouletteId][1][2]) then
			tRouletteMould_Info[nRouletteId]["Cost"]["EMoneyMono"] = RouletteMould_Bound[nRouletteId][1][3]
			tRouletteMould_Info[nRouletteId]["Cost"]["EmoneyMonoLog"] = "1000	01738	0	0	%d	"
			
			elseif (nNum >= RouletteMould_Bound[nRouletteId][2][1]) and (nNum <= RouletteMould_Bound[nRouletteId][2][2]) then
				tRouletteMould_Info[nRouletteId]["Cost"]["EMoneyMono"] = RouletteMould_Bound[nRouletteId][2][3]
				tRouletteMould_Info[nRouletteId]["Cost"]["EmoneyMonoLog"] = "1000	01738	0	0	%d	"
				
					else
					tRouletteMould_Info[nRouletteId]["Cost"]["EMoneyMono"] = RouletteMould_Bound[nRouletteId][3][3] 
					tRouletteMould_Info[nRouletteId]["Cost"]["EmoneyMonoLog"] = "1000	01738	0	0	%d	"
					
		end
	end
	local nEmoneyMono = tRouletteMould_Info[nRouletteId]["Cost"]["EMoneyMono"]
	if nEmoneyMono == nil then
		return true
	end
	
	if type(nEmoneyMono) ~= "number" then
		return false
	end
	
	
	
	local nUseEmoneyMono = nEmoneyMono*nNum
	local nUserEmoneyMono = Get_UserMonoEMoney(nUserId)
	
	if nUseEmoneyMono > nUserEmoneyMono then
		User_TalkChannel2005(string.format(tRouletteMould_Text["EMoneyMono"],nUseEmoneyMono),nUserId)
		return false
	end
	
	return true
end

-- 检测银两是否满足
function RouletteMould_ChkMoney(nRouletteId,nNum,nUserId)
	local nMoney = tRouletteMould_Info[nRouletteId]["Cost"]["Money"]
	
	if nMoney == nil then
