-- 检测背包空间
function RouletteMould_ChkSpace(nRouletteId,nNum,nNowUserId)
	local nUserId = nNowUserId or Get_UserId()
	local tAwardChart = tRouletteMould_Info[nRouletteId]["Reward"]
	local nSpace = 0
	local nSubSpace = 0
	
	-- 判断奖励是否是表数据
	if type(tAwardChart) ~= "table" then
		return false,nSpace
	end
	
	-- 获取奖励所需的背包空间
	nSpace = RewardTemplate_GetRandomSpace(tRouletteMould_Info[nRouletteId],"Reward",nUserId)*nNum
	-- 获取删除的物品所需的背包空间
	local tDelItem = tRouletteMould_Info[nRouletteId]["Cost"]
	nSubSpace = RewardTemplate_GetDelSpace(tDelItem,nUserId)*nNum
	
	nSpace = nSpace - nSubSpace
	
	--鸿运转盘特殊判断
	if nNum==10 then
		if nRouletteId==7048 then
			nSpace=11
		end
	end
	
	if nSpace > 0 and (not User_CheckLeftSpace(nSpace,nUserId)) then
		local sCoent = tRouletteMould_Info[nRouletteId]["NoSpace"]
		
		if sCoent == nil then
			sCoent = string.format(tRouletteMould_Text["NoSpace"],nSpace)
		end
		
		User_TalkChannel2005(sCoent,nUserId)
		return false
	end

	return true
end
--检测等级
function RouletteMould_ChkLevel(nRouletteId,nNowUserId)
	local nUserId = nNowUserId or Get_UserId()
	
	if tRouletteMould_Info[nRouletteId]["UserLevel"] == nil then
		return true
	end
	
	if tRouletteMould_Info[nRouletteId]["UserLevel"]["Level"] == nil then
		return true
	end
	
	if tRouletteMould_Info[nRouletteId]["UserLevel"]["Metempsychosis"] == nil then
		return true
	end
	
	
	local nLevel = tRouletteMould_Info[nRouletteId]["UserLevel"]["Level"]
	local nMetempsychosis = tRouletteMould_Info[nRouletteId]["UserLevel"]["Metempsychosis"]
	
	
	if User_JudgeLevelAndMetempsychosis(nLevel,nMetempsychosis,nUserId) then
		return true
	end
	
	sCoent = string.format(tRouletteMould_Text["TexasNoLevel"],nLevel)
	User_TalkChannel2005(sCoent,nUserId)
	
	return false
end

-- 设置掩码值
function RouletteMould_SetStc(nRouletteId,nNum,nUserId)
	local tStcIndex = tRouletteMould_Info[nRouletteId]["Stc"]
	local nNewNum = nNum or 1
	if tStcIndex == nil then
		return true
	end
	
	for i,v in pairs(tStcIndex) do
		local nEvent = v["EventType"]
		local nType = v["DataType"]
		local nData = Get_UserStatisticValue(nEvent,nType,nUserId)
		local nNowSingleData = nData%10000
		local nNowTotalData = (nData - nNowSingleData)/10000
		
		nNowSingleData = nNowSingleData + nNewNum
		nNowTotalData = nNowTotalData + nNewNum
		local nNewData = nNowTotalData*10000 + nNowSingleData
		
		Task_SetStatistic(nEvent,nType,nNewData,1,nUserId)
		Task_SetStcTimestamp(nEvent,nType,0,nUserId)
	end
	
	return true
end

-- 删除物品
function RouletteMould_DelItem(nRouletteId,nNum,nUserId)
	local tDelItem = tRouletteMould_Info[nRouletteId]["Cost"]["DeleteItem"]
	
	if tDelItem == nil then
		return false
	end
	
	local sDelItem = ""
	local sDelItemNum = ""
	
	for i,v in pairs(tDelItem) do
		local nItemId = v["Id"]
		local nMonopoly = v["Monopoly"] or 1
		local nSash = v["Sash"] or 0
		local nItemNum = v["ItemNum"] or 1
		local nSaveTime = v["SaveTime"] or 1
		nItemNum = nItemNum * nNum
		nSaveTime = RewardTemplate_DelSaveItem(nItemId,nSaveTime)
		
		if not Item_ChkMulItem(nItemId,nItemId,nItemNum,nMonopoly,nSash,nUserId,nSaveTime) then
			return false
		end
		if not Item_DelMulItem(nItemId,nItemId,nItemNum,nMonopoly,nSash,nUserId,nSaveTime) then
			return false
		end
		
		if sDelItem == "" then
			sDelItem = "" .. nItemId
			sDelItemNum = "" .. nItemNum
		else
			sDelItem = sDelItem .. "[" .. nItemId .. "]"
			sDelItemNum = sDelItemNum .. "[" .. nItemNum .. "]"
		end
	end
	
		if nRouletteId == 3977 then
			local sEmoneyLog = "350	21520	0	0	120	"
			Sys_SaveEmoneyBuy(sEmoneyLog,nUserId)
		end
		if nRouletteId == 3978 then
			local sEmoneyLog = "350	21521	0	0	120	"
			Sys_SaveEmoneyBuy(sEmoneyLog,nUserId)
		end
		if nRouletteId == 3979 then
			local sEmoneyLog = "350	21522	0	0	120	"
			Sys_SaveEmoneyBuy(sEmoneyLog,nUserId)
		end
		if nRouletteId == 3980 then
			local sEmoneyLog = "350	21523	0	0	120	"
			Sys_SaveEmoneyBuy(sEmoneyLog,nUserId)
		end
	
	
	local sText = string.format("0,0,%s,%s,%d,2,0,0",sDelItem,sDelItemNum,nRouletteId)
	RouletteMould_OutLog(sText,nUserId)
	return true
end

