-- 轮盘使用前的判断
function RouletteMould_Judge(nRouletteId,nNum,nUserId)
	-- 判断活动时间
	if not RouletteMould_ChkTime(nRouletteId,nUserId) then
		return false
	end
	
	if tRouletteMould_Info[nRouletteId]["Cost"] == nil then
		return false
	end
	
	-- 增加物品抵用券情况
	local bInstead = tRouletteMould_Info[nRouletteId]["Cost"]["Instead"]
	local bHave = false
	-- 判断使用上限
	if not RouletteMould_ChkStc(nRouletteId,nNum,nUserId) then
		RouletteMould_Msg(nRouletteId,"OverTip",nNum,nUserId)
		return false
	end
	
	-- 判断物品是否存在
	if not RouletteMould_ChkItem(nRouletteId,nNum,nUserId) then
		if bInstead == nil then
		RouletteMould_Msg(nRouletteId,"NoItem",nNum,nUserId)
		return false
		end
	else
		if bInstead ~= nil then
			bHave = true
		end
	end
	
	-- 判断天石是否满足
	if not RouletteMould_ChkEMoney(nRouletteId,nNum,nUserId) then
		if bInstead == nil or (not bHave) then
		RouletteMould_Msg(nRouletteId,"Emoney",nNum,nUserId)
		return false
		end
	end
	
	-- 判断银两是否满足
	if not RouletteMould_ChkMoney(nRouletteId,nNum,nUserId) then
		if bInstead == nil or (not bHave) then
		RouletteMould_Msg(nRouletteId,"Money",nNum,nUserId)
		return false
		end
	end
	
	-- 判断赠点天石是否满足
	if not RouletteMould_ChkEMoneyMono(nRouletteId,nNum,nUserId) then
		if bInstead == nil or (not bHave) then
		RouletteMould_Msg(nRouletteId,"EMoneyMono",nNum,nUserId)
		return false
		end
	end
	
	-- 判断气力是否满足
	if not RouletteMould_ChkStrength(nRouletteId,nNum,nUserId) then
		if bInstead == nil or (not bHave) then
		RouletteMould_Msg(nRouletteId,"StrengthValue",nNum,nUserId)
		return false
		end
	end
	
	-- 判断背包空间
	if not RouletteMould_ChkSpace(nRouletteId,nNum,nUserId) then
		return false
	end
	
	-- 上限检测
	if not NewTemplate_RandomUpperLimit(tRouletteMould_Info[nRouletteId],"Reward",nNum,nUserId) then
		return false
	end
	
	-- 删除物品
	if RouletteMould_DelItem(nRouletteId,nNum,nUserId) then
		if nRouletteId == 6876 or nRouletteId == 6877 or nRouletteId == 6878 or nRouletteId == 6879 then
			if RouletteMould_CostEMoneyMono(nRouletteId,nNum,nUserId) then
				return true
			end
		end
		if nRouletteId == 3437 then
			if nNum == 1 then
				local sEmoneyLog = "350	21480	0	0	1	"
				Sys_SaveEmoneyBuy(sEmoneyLog,nUserId)
			elseif nNum == 10 then
				local sEmoneyLog = "350	21480	0	0	10	"
				Sys_SaveEmoneyBuy(sEmoneyLog,nUserId)
			end
		end
		if nRouletteId == 6915 then
			if nNum == 1 then
				local sEmoneyLog = "350	21480	0	0	1	"
				Sys_SaveEmoneyBuy(sEmoneyLog,nUserId)
			elseif nNum == 10 then
				local sEmoneyLog = "350	21480	0	0	10	"
				Sys_SaveEmoneyBuy(sEmoneyLog,nUserId)
			end
		end
		if nRouletteId == 3438 then
			if nNum == 1 then
				local sEmoneyLog = "350	21482	0	0	1	"
				Sys_SaveEmoneyBuy(sEmoneyLog,nUserId)
			elseif nNum == 10 then
				local sEmoneyLog = "350	21482	0	0	10	"
				Sys_SaveEmoneyBuy(sEmoneyLog,nUserId)
			end
		end
		if nRouletteId == 6916 then
			if nNum == 1 then
				local sEmoneyLog = "350	21482	0	0	1	"
				Sys_SaveEmoneyBuy(sEmoneyLog,nUserId)
			elseif nNum == 10 then
				local sEmoneyLog = "350	21482	0	0	10	"
				Sys_SaveEmoneyBuy(sEmoneyLog,nUserId)
			end
		end
		if nRouletteId == 3439 then
			if nNum == 1 then
				local sEmoneyLog = "350	21484	0	0	1	"
				Sys_SaveEmoneyBuy(sEmoneyLog,nUserId)
			elseif nNum == 10 then
				local sEmoneyLog = "350	21484	0	0	10	"
				Sys_SaveEmoneyBuy(sEmoneyLog,nUserId)
			end
		end
		if nRouletteId == 6917 then
			if nNum == 1 then
				local sEmoneyLog = "350	21484	0	0	1	"
				Sys_SaveEmoneyBuy(sEmoneyLog,nUserId)
			elseif nNum == 10 then
				local sEmoneyLog = "350	21484	0	0	10	"
				Sys_SaveEmoneyBuy(sEmoneyLog,nUserId)
			end
		end
		return true
	end
	
	--12月轮盘活动
	if nRouletteId == 4290 then
		local nEvent = tRouletteMould_Info[nRouletteId]["Stc"][1]["EventType"]
		local nData = tRouletteMould_Info[nRouletteId]["Stc"][1]["DataType"]
		local nNumGet = Get_UserStatisticValue(nEvent,nData,nUserId)
		local nNum = nNumGet%10000
		--每人每天限量最多抽50次。
		--前10次花费5999天石，
		--从第11次起，到20次，每次5499天石,
		--从第21次起，到40次，每次4999天石,
		--从41次起，到50次，每次4499天石，
		if (nNum >= RouletteMould_HairBound[1][1]) and (nNum <= RouletteMould_HairBound[1][2]) then
			tRouletteMould_Info[nRouletteId]["Cost"]["Emoney"] = RouletteMould_HairBound[1][3]
			tRouletteMould_Info[nRouletteId]["Cost"]["EmoneyLog"] = "1000	01275	%d	%d	1	"
			elseif (nNum >= RouletteMould_HairBound[2][1]) and (nNum <= RouletteMould_HairBound[2][2]) then
				tRouletteMould_Info[nRouletteId]["Cost"]["Emoney"] = RouletteMould_HairBound[2][3]
				tRouletteMould_Info[nRouletteId]["Cost"]["EmoneyLog"] = "1000	01275	%d	%d	1	"
					elseif (nNum >= RouletteMould_HairBound[3][1]) and (nNum <= RouletteMould_HairBound[3][2]) then
					tRouletteMould_Info[nRouletteId]["Cost"]["Emoney"] = RouletteMould_HairBound[3][3] 
					tRouletteMould_Info[nRouletteId]["Cost"]["EmoneyLog"] = "1000	01275	%d	%d	1	"
						else
						tRouletteMould_Info[nRouletteId]["Cost"]["Emoney"] = RouletteMould_HairBound[4][3] 
						tRouletteMould_Info[nRouletteId]["Cost"]["EmoneyLog"] = "1000	01275	%d	%d	1	"
		end
	end
	-- 花费天石
	if RouletteMould_CostEMoney(nRouletteId,nNum,nUserId) then
		return true
	end
	
	-- 花费银两
	if RouletteMould_CostMoney(nRouletteId,nNum,nUserId) then
		return true
	end
	
	--12月轮盘活动
	if nRouletteId == 6947 then
