-- 德州轮盘
function RouletteMould_Texas(nUserId,nRouletteId)
	-- 获取玩家的德州轮盘抽奖次数
	local nTimes = RouletteFunc_GetTexasLotteryTimes(nUserId)
	
	-- 没有抽奖次数时给予提示
	if nTimes <= 0 then
		RouletteMould_Msg(nRouletteId,"TexasNoTime",nil,nUserId)
		return
	end
	
	-- 上限检测
	if not NewTemplate_RandomUpperLimit(tRouletteMould_Info[nRouletteId],"Reward",1,nUserId) then
		return false
	end
	
	-- 扣除一次抽奖次数
	if not RouletteFunc_AddTexasLotteryTimes(-1,nUserId) then
		return
	end
	
	local tReward = RewardTemplate_NewRandom(tRouletteMould_Info[nRouletteId],"Reward",nUserId)
	-- 打领取奖励的log
	local sText = string.format("0,0,0,0,%d,2,0,%d",nRouletteId,tReward[1]["tAward"][1]["NewPos"])
	RouletteMould_OutLog(sText,nUserId)
	if tReward == nil or tReward[1]["tAward"] == nil or tReward[1]["tAward"][1]["NewPos"] == nil then
		return
	end
	
	RouletteFunc_SendReward(tReward[1]["tAward"][1]["NewPos"],9,nUserId)
end

--新轮盘
function RouletteMould_NewtRoulette(nUserId,nRouletteId)
	
	-- 判断活动时间
	if not RouletteMould_ChkTime(nRouletteId,nUserId) then
		return false
	end
	
	if not RouletteMould_ChkLevel(nRouletteId,nUserId) then
		return false
	end
	
	-- 判断背包空间
	if not RouletteMould_ChkSpace(nRouletteId,1,nUserId) then
		return false
	end
	
	-- 上限检测
	if not NewTemplate_RandomUpperLimit(tRouletteMould_Info[nRouletteId],"Reward",1,nUserId) then
		return false
	end
	
	
	
	-- 设置掩码
	-- RouletteMould_SetStc(nRouletteId,1,nUserId)
	--获取掩码
	-- local nStcData = RouletteMould_GetStc(nRouletteId,1,nUserId)
	-- User_TalkChannel2005(tostring(nStcData))
	local tStcIndex = tRouletteMould_Info[nRouletteId]["Stc"]
	if tStcIndex == nil then
		return 0
	end
	
	local nEvent2 = tStcIndex[2]["EventType"]
	local nType2 = tStcIndex[2]["DataType"]
	
	if Task_ChkStcValue(nEvent2,nType2,"==",30001) then
		return 
	end
	
	local nEvent = tStcIndex[1]["EventType"]
	local nType = tStcIndex[1]["DataType"]
	
	local nStcData = Get_UserStatisticValue(nEvent,nType,nUserId)
	
	local nFreeNum = tRouletteMould_Info[nRouletteId]["RouletteFreeNum"] - nStcData
	--免费次数不能为空
	if nFreeNum == nil or nFreeNum <= 0 then
		return
	end
	
	Task_AddStatistic(nEvent,nType,1,1,nUserId)
	Task_SetStcTimestamp(nEvent,nType,0,nUserId)
	
	local nFlag,tReward = Probabil_RandomAward(tRouletteMould_Info[nRouletteId],"Reward")
	
	if tReward == nil or tReward[1]["tAward"] == nil or tReward[1]["tAward"][1]["NewPos"] == nil then
		return
	end
	
	if tReward[1]["tAward"][1]["NewBroadcast"] ~= nil then
		local nItemId = tReward[1]["tAward"][1]["RewardItem"][1]["Id"]
		RouletteFunc_TaskRewardResult(nRouletteId,nItemId,nUserId)
	end
	
	local bFlag,tAward = RouletteMould_Limit(nRouletteId,tReward[1]["tAward"][1],nUserId)

	tRouletteMould_Reward[nUserId] = {}
	tRouletteMould_Reward[nUserId]["RouletteId"] = nRouletteId
	tRouletteMould_Reward[nUserId]["Reward"] = tAward
	tRouletteMould_Reward[nUserId]["Time"] = 1
	
	return RouletteFunc_Publish(tReward[1]["tAward"][1]["NewPos"],nUserId,nFreeNum)
	

	
end

function RouletteMould_BuyAllItem(nUserId,nRouletteId)
	
	-- 判断活动时间
	if not RouletteMould_ChkTime(nRouletteId,nUserId) then
		return false
	end
	
	if not RouletteMould_ChkLevel(nRouletteId,nUserId) then
		return false
	end
	--判断二级密码是否打开
	if not Sys_IsOpenSecondPWD(nUserId) then
		Sys_MsgBox(tRouletteMould_Text["SecondPWD"],nil,nil,nUserId)
		return false
	end
	
	-- 判断背包空间
	if not RouletteMould_ChkSpace(nRouletteId,14,nUserId) then
		return false
	end
	
	if not RouletteMould_ChkEMoney(nRouletteId,1,nUserId) then
		RouletteMould_Msg(nRouletteId,"Emoney",1,nUserId)
	end
	
	local tStcIndex = tRouletteMould_Info[nRouletteId]["Stc"][2]
	
	local nEvent = tStcIndex["EventType"]
	local nType = tStcIndex["DataType"]
	
	if Task_ChkStcValue(nEvent,nType,"==",30001) then
		return 
	end
	
	if RouletteMould_CostEMoney(nRouletteId,1,nUserId) then
		local tReward = CommonFunc_Copy(tRouletteMould_Info[nRouletteId])
		
		for i,v in pairs(tReward["Reward"]) do
			
			if type(v) == 'table' then
				if v["RandomItemChanceType"] ~= 1 then
					v["RandomItemChanceType"] = 1
				end
			end
		end
		--获取奖励
		RewardTemplate_NewRandom(tReward,'Reward',nUserId)
		for j,k in pairs(tReward["Reward"]) do
			if type(k) == 'table' then
				if k["NewBroadcast"] ~= nil then
					local nItemId = k["RewardItem"][1]["Id"]
					
					
					
					RouletteFunc_TaskRewardResult(nRouletteId,nItemId,nUserId)
				end
			end
		end
		
		-- local tStcIndex = tRouletteMould_Info[nRouletteId]["Stc"][2]
		
		-- local nEvent = tStcIndex["EventType"]
		-- local nType = tStcIndex["DataType"]
		
		--下一个轮盘
		local nNextRouletteId = tRouletteMould_Info[nRouletteId]["NextRouletteId"]
		local nNextFreeNum = tRouletteMould_Info[nNextRouletteId]["RouletteFreeNum"]
		Task_SetStatistic(nEvent,nType,nNextRouletteId,1,nUserId)
		Task_SetStcTimestamp(nEvent,nType,0,nUserId)
		
		if nNextRouletteId == 30001 then  -- 30001为轮盘结束id
			RouletteFunc_QuerySchedule(nNextRouletteId,nUserId,0)
		end
		
		return SendTaskReward(nUserId,nNextRouletteId,11,nNextFreeNum)
		
		
	end
	
end

-- 限量操作
function RouletteMould_Limit(nRouletteId,tReward,nUserId)
	-- 判断是否单人限量
	local bFlag,tAward = RouletteMould_ChkGlobalStc(nRouletteId,tReward,nUserId)
	if not bFlag then
		return false,tAward
	end
	-- 判断是否有全服限量
	bFlag,tAward = RouletteMould_ChkGlobal(nRouletteId,tAward,nUserId)
	if not bFlag then
		return false,tAward
	end
	return true,tAward
end
-- 单人限量判断
function RouletteMould_ChkGlobalStc(nRouletteId,tReward,nUserId)
	local nEvent = tReward["EventType"]
	local nType = tReward["DataType"]
	if nEvent == nil or nType == nil then
		return true,tReward
	end
	local nSingleData = tReward["RewardData"] or 1
	local nDelay = tReward["RewardDelay"]
	local nTimeType = tReward["RewardTimeType"]
	if (nDelay ~= nil) and (nTimeType ~= nil) and Task_StcInterval(nEvent,nType,nDelay,nTimeType,nUserId) then
		Task_SetStatistic(nEvent,nType,0,1,nUserId)
		Task_SetStcTimestamp(nEvent,nType,0,nUserId)
	else
		local nData = Get_UserStatisticValue(nEvent,nType,nUserId)
		if nData >= nSingleData then
			local nIndex = tReward["FullIndex"]
			if nIndex == nil then
				return false,tReward
			end
			return true,tRouletteMould_Info[nRouletteId]["Reward"][nIndex]
		end
	end
	return true,tReward
end
-- 全服限量判断
function RouletteMould_ChkGlobal(nRouletteId,tReward,nUserId)
	local nGlobalId = tReward["GlobalId"]
	if nGlobalId == nil then
		return true,tReward
	end
	local nPos = tReward["Pos"] or 0
	local nMaxData = tReward["MaxData"] or 1
	local nData = Get_SysDynaGlobalData(nGlobalId,nPos)
	-- 单日全服限量
	local nDayPos = tReward["OtherPos"]
	local nDayMaxData = tReward["OtherMaxData"]
	if nDayPos ~= nil and nData < nMaxData then
		local nNewData = Get_SysDynaGlobalData(nGlobalId,nDayPos)
		if nNewData >= nDayMaxData then
			local nDayFullIndex = tReward["OtherFullIndex"] or tReward["FullIndex"]
			if nDayFullIndex ~= nil then
				return true,tRouletteMould_Info[nRouletteId]["Reward"][nDayFullIndex]
			end
			return false,tReward
		end
	elseif nData >= nMaxData then
		local nIndex = tReward["FullIndex"]
		if nIndex ~= nil then
			return true,tRouletteMould_Info[nRouletteId]["Reward"][nIndex]
		end
		return false,tReward
	end
	return true,tReward
end
-- 设置限量的掩码值
function RouletteMould_SetLimit(nRouletteId,tReward,nUserId)
	local nEvent = tReward["EventType"]
	local nType = tReward["DataType"]
	if nEvent ~= nil and nType ~= nil then
		Task_AddStatistic(nEvent,nType,1,1,nUserId)
		Task_SetStcTimestamp(nEvent,nType,0,nUserId)
	end
	local nGlobalId = tReward["GlobalId"]
	if nGlobalId ~= nil then
		local nPos = tReward["Pos"] or 0
		local nDayPos = tReward["OtherPos"]
		local nData = Get_SysDynaGlobalData(nGlobalId,nPos)
		Sys_SetSynaGlobalData(nGlobalId,nPos,nData + 1)
		if nDayPos ~= nil then
			local nNewData = Get_SysDynaGlobalData(nGlobalId,nDayPos)
			Sys_SetSynaGlobalData(nGlobalId,nDayPos,nNewData + 1)
		end
	end
end

-- 单抽
function RouletteMould_Extract(nUserId,nRouletteId)
	if tRouletteMould_Info[nRouletteId] == nil or tRouletteMould_Info[nRouletteId]["Reward"] == nil then
		return
	end
	
	-- 判断是否德州轮盘
	if tRouletteMould_Info[nRouletteId]["Texas"] then
		RouletteMould_Texas(nUserId,nRouletteId)
		return
	end
	--是否为新轮盘
	if tRouletteMould_Info[nRouletteId]["NewtRoulette"] then
		RouletteMould_NewtRoulette(nUserId,nRouletteId)
		return
	end
	
	-- 抽奖前置判断
	if not RouletteMould_Judge(nRouletteId,1,nUserId) then
		return
	end
	
	tRouletteMould_IsTurn[nUserId] = true
	
	-- 设置掩码
	RouletteMould_SetStc(nRouletteId,1,nUserId)
	
	local nFlag,tReward = Probabil_RandomAward(tRouletteMould_Info[nRouletteId],"Reward")
	
	if tReward == nil or tReward[1]["tAward"] == nil or tReward[1]["tAward"][1]["NewPos"] == nil then
		return
	end
	
	-- 判断是否限量了,限量了则给其它奖励
	local bFlag,tAward = RouletteMould_Limit(nRouletteId,tReward[1]["tAward"][1],nUserId)
	tRouletteMould_Reward[nUserId] = {}
	tRouletteMould_Reward[nUserId]["RouletteId"] = nRouletteId
	tRouletteMould_Reward[nUserId]["Reward"] = tAward
	tRouletteMould_Reward[nUserId]["Time"] = 1
	RouletteFunc_Publish(tAward["NewPos"],nUserId)
end

-- 重抽的背包空间判断
function RouletteMould_ChkAgainSpace(nRouletteId,nUserId)
	local bBloor,nSpace = RewardTemplate_ChkRandomSpace(tRouletteMould_Info[nRouletteId],"Reward",nUserId)
	
	if not bBloor then
		
		return false
	end
	
	return true
end

-- 重抽花费天石
function RouletteMould_ChkAgainEMoney(nRouletteId,nTime,nUserId)
	local nEMoney = tRouletteMould_Info[nRouletteId]["Again"]["EMoney"]
	
	if nEMoney == nil or type(nEMoney) ~= "number" then
		return false
	end
	
	local nAddType = tRouletteMould_Info[nRouletteId]["Again"]["AddType"]
	if nAddType == nil or nAddType == 1 then
		nTime = 1
	end
	
	local nUseEMoney = nEMoney*nTime
	local nMaxEMoney = tRouletteMould_Info[nRouletteId]["Again"]["MaxEMoney"]
	local nUserEMoney = Get_UserEMoney(nUserId)
	
	if nMaxEMoney ~= nil and nUseEMoney > nMaxEMoney then
		nUseEMoney = nMaxEMoney
	end
	
	if nUserEMoney < nUseEMoney then
		RouletteMould_Msg(nRouletteId,"AgainEMoney",nUseEMoney,nUserId)
		return false
	end
	
	if User_AddEMoney(-nUseEMoney,nUserId) then
		local sText = string.format("%d,0,0,0,%d,2,0,0",nUseEMoney,nRouletteId)
		RouletteMould_OutLog(sText,nUserId)
		local sLog = tRouletteMould_Info[nRouletteId]["Again"]["EmoneyLog"]
		if sLog ~= nil then
			RouletteMould_OutEmoneyLog(string.format(sLog,nUseEMoney,nUseEMoney),nUserId)
		end
		return true
	end
	
	return false
end

-- 重抽花费赠品天石
function RouletteMould_ChkAgainEMoneyMono(nRouletteId,nTime,nUserId)
	local nEMoneyMono = tRouletteMould_Info[nRouletteId]["Again"]["EMoneyMono"]
	
	if nEMoneyMono == nil or type(nEMoneyMono) ~= "number" then
