-- 重抽花费银两
function RouletteMould_ChkAgainMoney(nRouletteId,nTime,nUserId)
	local nMoney = tRouletteMould_Info[nRouletteId]["Again"]["Money"]
	
	if nEMoney == nil or type(nEMoney) ~= "number" then
		return false
	end
	
	local nUseMoney = nEMoney*nTime
	local nMaxMoney = tRouletteMould_Info[nRouletteId]["Again"]["MaxMoney"]

	if nMaxMoney ~= nil and nUseMoney > nMaxMoney then
		nUseMoney = nMaxMoney
	end
	
	if not User_CanPutMoney2Bag(-nUseMoney,nUserId) then
		RouletteMould_Msg(nRouletteId,"AgainMoney",nUseMoney,nUserId)
		return false
	end
	
	if User_AddMoney(-nUseMoney,nUserId) then
		local sText = string.format("0,0,1,%d,%d,2,0,0",nUseMoney,nRouletteId)
		RouletteMould_OutLog(sText,nUserId)
		return true
	end
	
	return false
end

-- 重抽花费气力
function RouletteMould_ChkAgainStrength(nRouletteId,nTime,nUserId)
	local nNeedStrengthValue = tRouletteMould_Info[nRouletteId]["Again"]["StrengthValue"]
	
	if nNeedStrengthValue == nil or type(nNeedStrengthValue) ~= "number" then
		return false
	end
	
	local nStrengthValue = nNeedStrengthValue*nTime
	local nUserStrengthValue = Get_UserStrengthValue(nUserId)
	
	if tRouletteMould_Info[nRouletteId]["Again"]["MaxStrengthValue"] then
		local nMaxStrengthValue = tRouletteMould_Info[nRouletteId]["Again"]["MaxStrengthValue"]
		if nMaxStrengthValue ~= nil and nStrengthValue > nMaxStrengthValue then
			nStrengthValue = nMaxStrengthValue
		end
	end
	
	if nUserStrengthValue < nStrengthValue then
		RouletteMould_Msg(nRouletteId,"AgainStrengthValue",nUserStrengthValue,nUserId)
		return false
	end
	
	if User_AddStrengthValue(-nStrengthValue,nUserId) then
		local sText = string.format("0,0,12,%d,%d,2,0,0",nStrengthValue,nRouletteId)
		RouletteMould_OutLog(sText,nUserId)
		return true
	end
	
	return false
end

-- 重抽花费判断
function RouletteMould_AgainJudege(nRouletteId,nUserId)
	if tRouletteMould_Info[nRouletteId]["Again"] == nil then
		return false
	end
	
	if tRouletteMould_Reward[nUserId] == nil then
		return false
	end
	
	-- 背包空间判断
	if not RouletteMould_ChkAgainSpace(nRouletteId,nUserId) then
		return false
	end
	
	local nAgainTime = tRouletteMould_Reward[nUserId]["Time"] or 1
	
	-- 重抽花费天石
	if RouletteMould_ChkAgainEMoney(nRouletteId,nAgainTime,nUserId) then
		return true
	end
	
	-- 重抽花费银两
	if RouletteMould_ChkAgainMoney(nRouletteId,nAgainTime,nUserId) then
		return true
	end
	
	-- 重抽花费赠品天石
	if RouletteMould_ChkAgainEMoneyMono(nRouletteId,nAgainTime,nUserId) then
		return true
	end

	-- 重抽花费气力
	if RouletteMould_ChkAgainStrength(nRouletteId,nAgainTime,nUserId) then
		return true
	end
	
	return false
end

-- 重抽
function RouletteMould_Again(nUserId,nRouletteId)
	if tRouletteMould_Info[nRouletteId] == nil or tRouletteMould_Info[nRouletteId]["Reward"] == nil then
		return
	end
	
	-- 重抽花费判断
	if not RouletteMould_AgainJudege(nRouletteId,nUserId) then
		return
	end
	
	local nFlag,tReward = Probabil_RandomAward(tRouletteMould_Info[nRouletteId],"Reward")
	
	if tReward == nil or tReward[1]["tAward"] == nil or tReward[1]["tAward"][1]["NewPos"] == nil then
		return
	end

	tRouletteMould_Reward[nUserId]["RouletteId"] = nRouletteId
	tRouletteMould_Reward[nUserId]["Reward"] = tReward[1]["tAward"][1]
	tRouletteMould_Reward[nUserId]["Time"] = tRouletteMould_Reward[nUserId]["Time"] + 1
	RouletteFunc_Publish(tReward[1]["tAward"][1]["NewPos"],nUserId)
end

-- 十连抽
function RouletteMould_TenExtract(nUserId,nRouletteId)
	if tRouletteMould_Info[nRouletteId] == nil or tRouletteMould_Info[nRouletteId]["Reward"] == nil then
		return
	end
	
	-- 不支持十连抽
	if tRouletteMould_Info[nRouletteId]["NoSupportTen"] ~= nil then
		RouletteMould_Msg(nRouletteId,"NoSupportTenRou",nil,nUserId)
		return
	end
	-- 抽奖前置判断
	if not RouletteMould_Judge(nRouletteId,10,nUserId) then
		return
	end

	
	-- 设置掩码
	RouletteMould_SetStc(nRouletteId,10,nUserId)
	

	local sIndex = ""
	local sPos = ""
	
	for i = 1,10 do
	
	
		local tReward = RewardTemplate_NewRandom(tRouletteMould_Info[nRouletteId],"Reward",nUserId)
		
		
		
		if tReward == nil or tReward[1]["tAward"] == nil or tReward[1]["tAward"][1]["NewPos"] == nil then
			return
		end
		
		if i == 10 then
			sIndex = sIndex .. tReward[1]["tAward"][1]["NewPos"]
		else
			sIndex = sIndex .. tReward[1]["tAward"][1]["NewPos"] .. " "
		end
		
		sPos = sPos .. "[" .. tReward[1]["tAward"][1]["NewPos"] .. "]"
		if tReward[1]["tAward"][1]["EmoneyLog"] ~= nil then
			-- Sys_SaveEmoneyBuy(tReward[1]["tAward"][1]["EmoneyLog"],nUserId)
		end
	end
	
	local sText = string.format("0,0,0,0,%d,2,0,%s",nRouletteId,sPos)
	RouletteMould_OutLog(sText,nUserId)
	RouletteFunc_SendTenReward(sIndex,nUserId)
end

-- 领取奖励
function RouletteMould_Reward(nUserId)
	if tRouletteMould_Reward[nUserId] == nil or type(tRouletteMould_Reward[nUserId]) ~= "table" then
		return
	end

	local nRouletteId = tRouletteMould_Reward[nUserId]["RouletteId"]
	local tReward = tRouletteMould_Reward[nUserId]["Reward"]
	-- 设置限量掩码
	RouletteMould_SetLimit(nRouletteId,tReward,nUserId)
	
	if tRouletteMould_Info[nRouletteId]["Reward"]["LogId"] ~= nil then
		tReward["LogId"] = tRouletteMould_Info[nRouletteId]["Reward"]["LogId"]
	else
		tReward["LogId"] = tRouletteMould_Reward[nUserId]["Reward"]["LogId"]
	end
	
	local sReward = RewardTemplate_Reward(tReward,nUserId)
	-- if RewardTemplate_Reward(tReward,nUserId) then
	if sReward then
		if tReward["EmoneyLog"] ~= nil then
			Sys_SaveEmoneyBuy(tReward["EmoneyLog"],nUserId)
		end
		-- 打领取奖励的log
		local sText = string.format("0,0,0,0,%d,2,0,%d",nRouletteId,tReward["NewPos"])
		RouletteMould_OutLog(sText,nUserId)
		local sNewLog = tRouletteMould_Info[nRouletteId]["EmoneyCount"]
		if sNewLog ~= nil then
			RouletteMould_OutEmoneyLog(sNewLog,nUserId)
		end
		tRouletteMould_Reward[nUserId] = nil
	end
	
	tRouletteMould_IsTurn[nUserId] = false
	
	-- 190417[英文征服][活动脚本]5月玩灵珠有好礼（5月28日-6月10日）
	if nRouletteId ~= nil then 
		if nRouletteId == 7033 or nRouletteId == 7034 or nRouletteId == 7035 then
			DragonGift_UseRoulette(nRouletteId,nUserId)
		end 
		
		if nRouletteId == 7058 or nRouletteId == 7059 or nRouletteId == 7060 or nRouletteId == 7061 then
			OctMoMoAct_AddCPRank(99,nUserId)
		end 
		
	end
end

