-- 打开轮盘
function RouletteMould_Main(nIndex,nNowUserId)
	local nUserId = nNowUserId or Get_UserId()
	
	if tRouletteMould_IsTurn[nUserId] ~= nil and tRouletteMould_IsTurn[nUserId] then
		RouletteMould_Reward(nUserId)
		tRouletteMould_IsTurn[nUserId] = false
	end
	-- 判断活动时间
	if not RouletteMould_ChkTime(nIndex) then
		return
	end
	
	local nRouletteId = tRouletteMould_Info[nIndex]["Id"]
	
	if nRouletteId == nil then
		return
	end
	
	-- 打开轮盘界面
	RouletteFunc_Open(nRouletteId,nUserId)
end

--打开新轮盘界面
function RouletteMould_Schedule(nNowUserId)
	local nUserId = nNowUserId or Get_UserId()
	local nRouletteId = 30002 --普通服轮盘起始id
	
	if SpecialServer_ChkNoGiftServer() then
		nRouletteId = 30005  ----激情服轮盘起始id
	end
	
	if nRouletteId == nil then
		return
	end
	
	local tStcIndex = tRouletteMould_Info[nRouletteId]["Stc"]
	if tStcIndex == nil then
		return 0
	end
	
	local nEvent = tStcIndex[2]["EventType"]
	local nType = tStcIndex[2]["DataType"]
	local nStcData = Get_UserStatisticValue(nEvent,nType,nUserId)
	local nNowRouletteId = 0
	
	if nStcData == 0 or nStcData == nil then
		nNowRouletteId = nRouletteId
	else
		nNowRouletteId = nStcData
	end
	
	if not RouletteMould_ChkLevel(nNowRouletteId,nUserId) then
		return
	end
	
	if nNowRouletteId == 30001 then -- 30001为轮盘结束id
		RouletteFunc_Open(nNowRouletteId,nUserId,0)
		return
	end
	
	
	local tNewStcIndex = tRouletteMould_Info[nNowRouletteId]["Stc"]
	local nEventFree = tNewStcIndex[1]["EventType"]
	local nTypeFree = tNewStcIndex[1]["DataType"]
	local nFreeStcData = Get_UserStatisticValue(nEventFree,nTypeFree,nUserId)
	local nFreeNum = tRouletteMould_Info[nNowRouletteId]["RouletteFreeNum"] - nFreeStcData
	
	RouletteFunc_Open(nNowRouletteId,nUserId,nFreeNum)
	
end
------------------------------上线触发---------------------------
function RouletteMould_NewRouletteInter()
	local nUserId = Get_UserId()
	local nRouletteId = 30002 --普通服轮盘起始id
	if nRouletteId == nil then
		return
	end
	
	if SpecialServer_ChkNoGiftServer() then
		nRouletteId = 30005 ----激情服轮盘起始id
	end
	
	local tStcIndex = tRouletteMould_Info[nRouletteId]["Stc"]
	if tStcIndex == nil then
		return 0
	end
	
	local nEvent = tStcIndex[2]["EventType"]
	local nType = tStcIndex[2]["DataType"]
	local nStcData = Get_UserStatisticValue(nEvent,nType,nUserId)
	local nNowRouletteId = 0
	
	if nStcData == 0 or nStcData == nil then
		nNowRouletteId = nRouletteId
	else
		nNowRouletteId = nStcData
	end
	
	-- if not RouletteMould_ChkLevel(nNowRouletteId,nUserId) then
		-- return
	-- end
	
	if nNowRouletteId == 30001 then  -- 30001为轮盘结束id
		RouletteFunc_QuerySchedule(nNowRouletteId,nUserId,0)
		return
	end
	
	local tNewStcIndex = tRouletteMould_Info[nNowRouletteId]["Stc"]
	local nEventFree = tNewStcIndex[1]["EventType"]
	local nTypeFree = tNewStcIndex[1]["DataType"]
	local nFreeStcData = Get_UserStatisticValue(nEventFree,nTypeFree,nUserId)
	
	local nFreeNum = tRouletteMould_Info[nNowRouletteId]["RouletteFreeNum"] - nFreeStcData
	
	RouletteFunc_QuerySchedule(nNowRouletteId,nUserId,nFreeNum)
end
