-- ===3316235,'盛夏果实转盘'
tItem[3316235] = tItem[3316235] or {}
tItem[3316235]["Function"] = function (nItemId,sItemName)
	
	-- 不在活动时间
	if (not Sys_ChkFullTime(tActivityTime["IrrigateSacredTree"]["ActivityTime"])) or (not IrrigateSacredTree_ServerDisting()) then
		-- 删除物品
		local nIrrigateSacredTree_ItemNum = Get_CountItemType(nItemId,0)
		if not Item_DelMulItem(nItemId,nItemId,nIrrigateSacredTree_ItemNum) then
			return
		end
		
		-- 删除所有物品 打log
		Sys_SaveActionFestivalLog(string.format(tIrrigateSacredTree_Cont["Log"]["DelTimeOut"],nItemId,nIrrigateSacredTree_ItemNum))
		return
	end
	
	-- 等级限制
	if not IrrigateSacredTree_ChkLevAndMete(nIrrigateSacredTree_UserId) then
		return
	end
	
	RouletteMould_Main(4499)
end
